    vector<ll> parent;

    UnionFindStructure(ll n) {
        parent.resize(n);
        for (ll i = 0; i < n; ++i) parent[i] = i;
    }

    ll find_parent(ll a) {
        if (parent[a] == a) return a;
        parent[a] = find_parent(parent[a]);
        return parent[a];
    }

    void merge_sets(ll a, ll b) {
        a = find_parent(a);
        b = find_parent(b);
        if (a != b) {
