import java.util.*;

public class Main {
    static final long MOD = 1000000007;

    static class UnionFindStructure {
        long[] parent;

        public UnionFindStructure(int n) {
            parent = new long[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public long findParent(long a) {
            if (parent[(int)a] == a) {
                return a;
            }
            parent[(int)a] = findParent(parent[(int)a]);
            return parent[(int)a];
        }

        public void mergeSets(long a, long b) {
            a = findParent(a);
            b = findParent(b);
            if (a != b) {
                Random rand = new Random();
                if (rand.nextInt(2) == 0) {
                    long temp = a;
                    a = b;
                    b = temp;
                }
                parent[(int)b] = a;
            }
        }
    }

    static long getNumberOfCycles(int total, int k) {
        UnionFindStructure uf = new UnionFindStructure(total);
        for (int i = 1; i < total; i++) {
            int target = (k * i) % total;
            uf.mergeSets(i, target);
        }
        boolean[] visited = new boolean[total];
        long countCycles = 0;
        for (int i = 1; i < total; i++) {
            long root = uf.findParent(i);
            if (!visited[(int)root]) {
                visited[(int)root] = true;
                countCycles++;
            }
        }
        return countCycles;
    }

    static long computeNumberOfSolutions(int total, int k) {
        long cycles;
        if (k == 0) {
            cycles = total - 1;
        } else if (k == 1) {
            cycles = total;
        } else {
            cycles = getNumberOfCycles(total, k);
        }
        long result = 1;
        for (int i = 0; i < cycles; i++) {
            result = (result * total) % MOD;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        System.out.println(computeNumberOfSolutions(p, k));
        int dummy = sc.nextInt(); // read dummy input
        sc.close();
    }
}
